mapper.select:
select s.id, s.name, s.category_id, s.price, s.image, s.description,
s.status, s.update_time, c.name as category_name from setmeal s left join category c on s.category_id = c.id 

    and s.name like concat('%', #{name}, '%')


    and s.category_id = #{categoryId}


    and s.status = #{status}


order by s.create_time desc
